package io.knowledgebrain.collaboration;
import jakarta.servlet.http.HttpServletRequest;
import java.io.IOException;
import java.util.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
@RestController
@ConditionalOnProperty(name="brain.collaboration.api.enabled",havingValue="true")
class GroupController {
 record Page(List<GroupStore.Group> items,UUID nextAfter){}
 record History(List<GroupStore.Revision> items,Long nextBefore){}
 private final GroupStore store;private final GroupSpaceClient space;private final String origin;
 GroupController(GroupStore store,GroupSpaceClient space,@Value("${brain.collaboration.browser-origin}")String origin){this.store=store;this.space=space;this.origin=origin;}
 private byte[] body(HttpServletRequest r)throws IOException{var bytes=r.getInputStream().readNBytes(65537);if(bytes.length>65536)throw new ResponseStatusException(HttpStatus.PAYLOAD_TOO_LARGE,"Request too large");return bytes;}
 private String token(HttpServletRequest r){if(!r.isSecure())throw GroupInput.bad();var tokens=new ArrayList<String>();for(String header:Collections.list(r.getHeaders("Cookie")))for(String part:header.split(";")){var pair=part.trim().split("=",2);if(pair.length==2&&pair[0].equals("__Host-brain_guest"))tokens.add(pair[1]);}if(tokens.size()!=1||!tokens.getFirst().matches("[A-Za-z0-9_-]{43}"))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Browser session required");return tokens.getFirst();}
 private void write(HttpServletRequest r){if(Collections.list(r.getHeaders("Origin")).size()!=1||!origin.equals(r.getHeader("Origin"))||r.getHeader("Sec-Fetch-Site")!=null&&!"same-origin".equals(r.getHeader("Sec-Fetch-Site")))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Same-origin request required");if(!MediaType.APPLICATION_JSON_VALUE.equalsIgnoreCase(Optional.ofNullable(r.getContentType()).orElse("").split(";",2)[0].trim()))throw new ResponseStatusException(HttpStatus.UNSUPPORTED_MEDIA_TYPE,"JSON required");query(r,Set.of());}
 private void query(HttpServletRequest r,Set<String> allowed){if(r.getQueryString()!=null&&r.getQueryString().length()>256)throw GroupInput.bad();for(var e:r.getParameterMap().entrySet())if(!allowed.contains(e.getKey())||e.getValue().length!=1)throw GroupInput.bad();}
 private int limit(HttpServletRequest r,int maximum,int fallback){var value=r.getParameter("limit");if(value==null)return fallback;if(!value.matches("[1-9][0-9]{0,2}")||Integer.parseInt(value)>maximum)throw GroupInput.bad();return Integer.parseInt(value);}
 private String trace(HttpServletRequest r){var value=r.getHeader("traceparent");if(value==null||!value.matches("00-[0-9a-f]{32}-[0-9a-f]{16}-[0-9a-f]{2}")||value.substring(3,35).equals("0".repeat(32))||value.substring(36,52).equals("0".repeat(16))){value="00-"+UUID.randomUUID().toString().replace("-","")+"-"+UUID.randomUUID().toString().replace("-","").substring(0,16)+"-01";}return value;}
 private void readable(HttpServletRequest r,Set<String> allowed)throws IOException{query(r,allowed);if(body(r).length!=0)throw GroupInput.bad();}
 private GroupStore.Group require(UUID id,String token,String trace){var access=space.access(token,List.of(id),trace);var group=store.owned(id,access.principalId());if(group.state().equals("ACTIVE")&&access.grants().stream().noneMatch(g->g.groupId().equals(id)&&g.spaceId().equals(group.spaceId())))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Group unavailable");return group;}
 private ResponseEntity<GroupStore.Group> response(GroupStore.Group group){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).eTag("\"gr"+group.version()+"\"").body(group);}
 @PostMapping("/api/groups") ResponseEntity<GroupStore.Group> create(HttpServletRequest r)throws IOException{var token=token(r);write(r);var keys=Collections.list(r.getHeaders("Idempotency-Key"));if(keys.size()!=1||!keys.getFirst().matches("[0-9a-f]{32}"))throw GroupInput.bad();var settings=GroupInput.settings(body(r));var trace=trace(r);var owner=space.access(token,List.of(),trace).principalId();var group=store.request(owner,keys.getFirst(),settings.title(),settings.description(),trace.substring(3,35));return response(complete(group,token,trace));}
 private GroupStore.Group complete(GroupStore.Group group,String token,String trace){if(group.state().equals("ACTIVE"))return require(group.groupId(),token,trace);var access=space.provision(token,group.groupId(),trace);if(!access.principalId().equals(group.creatorPrincipalId())||access.grants().size()!=1)throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Group Space unavailable");return store.activate(group.groupId(),group.creatorPrincipalId(),access.grants().getFirst().spaceId(),trace.substring(3,35));}
 @PostMapping("/api/groups/{groupId}/complete") ResponseEntity<GroupStore.Group> resume(@PathVariable String groupId,HttpServletRequest r)throws IOException{var token=token(r);write(r);var json=GroupInput.json(body(r));if(json==null||!json.isObject()||json.size()!=0)throw GroupInput.bad();var trace=trace(r);return response(complete(require(GroupInput.id(groupId),token,trace),token,trace));}
 @GetMapping("/api/groups/{groupId}") ResponseEntity<GroupStore.Group> detail(@PathVariable String groupId,HttpServletRequest r)throws IOException{var token=token(r);readable(r,Set.of());return response(require(GroupInput.id(groupId),token,trace(r)));}
 @GetMapping("/api/groups") ResponseEntity<Page> list(HttpServletRequest r)throws IOException{var token=token(r);readable(r,Set.of("after","limit"));var trace=trace(r);var principal=space.access(token,List.of(),trace).principalId();int limit=limit(r,100,20);var after=r.getParameter("after");var rows=store.candidates(principal,after==null?null:GroupInput.id(after),limit);boolean more=rows.size()>limit;var scan=rows.subList(0,Math.min(limit,rows.size()));var ids=scan.stream().filter(g->g.state().equals("ACTIVE")).map(GroupStore.Group::groupId).toList();var allowed=space.access(token,ids,trace);if(!principal.equals(allowed.principalId()))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Session changed");var visible=scan.stream().filter(g->g.state().equals("PENDING")||allowed.grants().stream().anyMatch(a->a.groupId().equals(g.groupId())&&a.spaceId().equals(g.spaceId()))).toList();return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(new Page(visible,more?scan.getLast().groupId():null));}
 @GetMapping("/api/groups/{groupId}/revisions") ResponseEntity<History> history(@PathVariable String groupId,HttpServletRequest r)throws IOException{var token=token(r);readable(r,Set.of("before","limit"));var group=require(GroupInput.id(groupId),token,trace(r));int limit=limit(r,10,10);long before=Long.MAX_VALUE;var value=r.getParameter("before");if(value!=null){try{if(!value.matches("[1-9][0-9]{0,18}"))throw GroupInput.bad();before=Long.parseLong(value);}catch(NumberFormatException e){throw GroupInput.bad();}}var rows=store.history(group.groupId(),before,limit);var page=rows.subList(0,Math.min(limit,rows.size()));return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(new History(page,rows.size()>limit?page.getLast().version():null));}
}
